def copy_user_phone_to_profile(apps, schema_editor):
    Utilisateur = apps.get_model("api", "Utilisateur")
    ProfilUtilisateur = apps.get_model("api", "ProfilUtilisateur")

    for user in Utilisateur.objects.all().iterator():
        telephone = getattr(user, "telephone", "") or ""
        if not telephone:
            continue

        profile, _created = ProfilUtilisateur.objects.get_or_create(
            utilisateur_id=user.id_user,
            defaults={"nom": user.pseudo or "", "telephone": telephone},
        )
        if not profile.telephone:
            profile.telephone = telephone
            profile.save(update_fields=["telephone"])


